import{_ as i,l as n,o as e,c as o,v as t,p as l,x as r,d as h,i as p,S as M}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"基差互换","description":"","frontmatter":{"title":"基差互换","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/basis-swap.md","filePath":"quant/basis-swap.md","lastUpdated":1789023840000}'),E={name:"quant/basis-swap.md"};function d(u,a,B,c,A,S){const s=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="基差互换" tabindex="-1">基差互换 <a class="header-anchor" href="#基差互换" aria-label="Permalink to &quot;基差互换&quot;">​</a></h1><div class="epigraph"><p>同一货币下，不同期限的浮动指数不再能由一条曲线生成；3M 对 6M 的价差本身可交易，必须再自助一条投影曲线。</p><footer>—— Mercurio, Interest Rates and The Credit Crunch: New Formulas and Market Models, 2009；Bianchetti, Two Curves, One Price, Risk, 2010</footer></div><p>基差互换（basis swap）交换两串浮动利息：同一货币、不同指数或不同期限，价差加在其中一条腿上使合约初始公允价值为零。危机前，1M、3M、6M LIBOR 被当成同一无风险短端的不同复利，期限基差只有几个基点；危机中 3s6s、LIBOR–OIS 撑开到必须单独建模。Mercurio（2009）写出多曲线下 cap、FRA 与基差的公式；Bianchetti（2010）把「两条曲线、一个价格」写成市场惯例；Fujii、Shimada 与 Takahashi（2010）讨论有抵押时多条互换曲线如何同时自助。本篇写单币种期限基差与指数基差，不写已单独成篇的<a href="/quant/xccy-basis">交叉货币基差</a>。它是<a href="/quant/multi-curve-ois">OIS 与多曲线</a>的可交易腿，也是 <a href="/quant/lmm">LMM</a> 在停用 LIBOR 之后仍要保留多条 tenor 结构的原因。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单曲线恒等式说：3M 远期应由贴现因子之比给出，六个 3M 复利应对齐一个 6M。一旦 3M 与 6M 指数含不同的银行信用、流动性与定盘微观结构，恒等式变成带价差的市场。基差互换把这个价差变成报价：例如付 3M、收 6M 减去 \\(b\\) 个基点。\\(b\\) 的期限结构是新的状态变量。问题是估值：折现用哪条曲线、两条投影如何自助、期权的标的是哪一个远期，以及风险报告如何把「3M 的 5Y」与「6M 的 5Y」分成不同的<a href="/quant/key-tenor-dv01">关键期限 DV01</a>。</p><p>第二层是指数改革。LIBOR–OIS 曾是信用与无担保融资的晴雨表；转到 SOFR 之后，同类对象变成期限 SOFR 对隔夜复利、SOFR 对有效联邦基金、或 SOFR 对担保隔夜融资的不同口径。名字都叫 basis，微观不同。把 2011 年的 3s6s 回归系数套到 2025 年的 SOFR 基差上，是在估计一段已经关闭的市场。</p><h3 id="浮动对浮动-不是「再做一个互换」" tabindex="-1">浮动对浮动，不是「再做一个互换」 <a class="header-anchor" href="#浮动对浮动-不是「再做一个互换」" aria-label="Permalink to &quot;浮动对浮动，不是「再做一个互换」&quot;">​</a></h3><p>普通利率互换是固定对浮动，风险主要是固定端久期对浮动指数。基差互换两腿都是浮动，平行移动下净久期接近零，剩余的是两条投影曲线的相对移动。用单一互换 DV01 去对冲基差簿，会在水平冲击上过度对冲、在基差冲击上完全不对冲。这与<a href="/quant/swap-spread">互换价差</a>（互换对国债）不同：那里一条腿是政府曲线；这里两条腿都是银行或 RFR 指数，国债便利不直接出现。</p><p><span class="marginnote">报价惯例必须写清：价差加在短期限腿还是长期限腿、年分数、支付频率是否错配、是否交换名义。3s6s 在美元与欧元上的符号习惯不必相同。内部把基差存成「6M 投影减 3M 投影的平价差」，再映射到经纪商惯例。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>曲线。</strong> 先自助抵押折现 \\(P^D\\)（OIS 或 SOFR OIS）。再对主指数（如 3M）用固定对浮动互换自助投影 \\(F^{3M}\\)。基差互换给出 6M 相对 3M 的信息，用来自助 \\(F^{6M}\\)，而不是再用 6M 固定对浮动单独当唯一输入——二者应交叉检验。FRA 与期货是短端投影的直接观察，但期货有凸性，不能当远期本身，见<a href="/quant/curve-bootstrap">曲线自助</a>。</p><p>多曲线下，一笔 3s6s 基差互换的现值是两条浮动腿按 \\(P^D\\) 折现的差。每条腿的期望用各自投影远期。不要用 \\(P^{6M}\\) 去折现 6M 现金流：\\(P^{6M}\\) 只是生成远期的辅助对象。Bianchetti 的「一个价格」指所有现金流最终都走折现曲线。</p><p><strong>风险。</strong> 对 \\(P^D\\) 做关键冲击，得到折现 DV01（两腿年分数若不同，折现风险不为零）。对 \\(F^{3M}\\)、\\(F^{6M}\\) 分别做关键冲击，得到两列投影 01，符号相反、期限结构不必镜像。对冲：用 3M 互换（或 SOFR 3M 产品）与 6M 互换的篮子解线性方程，使两列关键 01 落入限额；剩余的折现 01 用 OIS 对冲。单因子 <a href="/quant/hull-white">Hull-White</a> 只有一个 \\(r\\)，做不到两列投影，基差只能外生冻结。</p><h3 id="市场模型里的-tenor-结构" tabindex="-1">市场模型里的 tenor 结构 <a class="header-anchor" href="#市场模型里的-tenor-结构" aria-label="Permalink to &quot;市场模型里的 tenor 结构&quot;">​</a></h3><p>LMM 的状态是某一 tenor 的简单远期。多曲线之后，3M LMM 与 6M LMM 是两套状态，其间的瞬时相关与基差扩散要另设。Mercurio 给出用折现曲线加各 tenor 远期的定价公式，caplet 的标的是该 tenor 的投影远期，贴现用 \\(P^D\\)。把 1997 年单曲线 LMM 的漂移原样用于 6M，再拿 3M 波动去标 3s6s 期权，相关结构是错的。工程上常见的简化是：香草用各 tenor 自己的波动曲面，基差用较慢的因子或冻结，不为 3s6s 单独建满秩 LMM——流动性不够支撑那么多参数。</p><p><a href="/quant/hjm">HJM</a> 可以对两条瞬时远期曲线写耦合波动，漂移条件要对每条可交易折现（或对每条投影的适当计价物）分别成立。实践成本通常高于「折现一条 Hull–White，投影基差当确定性调整」。只有当账簿含大量基差期权或 CMS 对错误 tenor 的暴露时，才值得让基差随机。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>期限基差的经济来源是指数本身的信用与流动性，而不是折现。6M LIBOR 含更长的无担保银行风险，危机中高于两个 3M 的复利；OIS 几乎不含这笔信用，LIBOR–OIS 变宽。担保之后，SOFR 隔夜复利与「期限 SOFR」仍可因凸性、在险期限、期货微观与合成而不同，但量级和危机中的银行信用基差不是同一量级。Johannes–Sundaresan 讨论的抵押，影响的是折现与互换利率水平，会同时抬或压两腿，对纯期限基差是二阶，除非两腿的抵押惯例不同。</p><p>错配支付频率会留下微小的固定端式暴露：3M 腿一年付四次、6M 腿付两次，年分数与折现时点不同，平行曲线移动仍有残差。这不是曲率交易，是日计数。做大名义之前应用关键点把残差扫出来，必要时用一笔小的固定对浮动补齐，以免基差簿看起来像<a href="/quant/curve-butterfly">曲线蝶式</a>。</p><p><span class="marginnote">LIBOR–OIS 曾被当成银行体系压力的近实时指标。SOFR–OIS（或 SOFR–FF）更多反映担保与准备金结构。同一张「基差监控图」换指数而不换解释，会在 2023 年之后制造虚假警报。</span></p><h3 id="与互换价差、交叉货币的边界" tabindex="-1">与互换价差、交叉货币的边界 <a class="header-anchor" href="#与互换价差、交叉货币的边界" aria-label="Permalink to &quot;与互换价差、交叉货币的边界&quot;">​</a></h3><p>互换价差连的是互换与国债；单币种基差连的是两个浮动指数；交叉货币基差连的是两种货币的浮动加本金交换。三者可以相关——美元短缺时 xccy、LIBOR–OIS、国债特殊性一起动——但对冲工具不能借用。用收 LIBOR–OIS 去对冲 EURUSD basis，留下外汇和监管日历。风控科目应是「曲线 × 指数 × 货币」，而不是一个叫 basis 的桶。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在投影曲线上用全局插值，使 3M 的 10Y 扰动改变 6M 的 30Y 远期，Ho 意义上的三角形在基差维度上崩掉。不要把期货凸性塞进基差节点当「真实远期」。不要为稀疏的 1s3s 报价建一条每天重校准的随机基差因子，参数会吸收噪声。期权smile 在各 tenor 上可以不同，3s6s 的 cap 更薄，模型风险大于香草。</p><p>LIBOR 停用后，残余合同的后备把 IBOR 换成 RFR 加固定利差，期限基差的一部分被冻结进利差调整，另一部分变成 RFR 期限结构。账簿要按协议日切换曲线，而不是把旧 3s6s 历史继续当风险因子。见<a href="/quant/sofr-transition">SOFR 过渡与后备</a>。</p><p><span class="marginnote">实现测试：把 OIS 曲线平行上移、两条投影相对不动，基差互换的 PnL 应只有年分数错配量级；把 6M 投影相对 3M 上移 1bp，PnL 应接近基差 DV01。过不了这两项，折现与投影接反了。</span></p>',26)),(e(),l(M,null,{default:r(()=>[p(s,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%8A%98%E7%8E%B0%20P%5ED%3A%20OIS%2FSOFR%22%5D%20--%3E%20PV%5B%22%E5%9F%BA%E5%B7%AE%E4%BA%92%E6%8D%A2%E7%8E%B0%E5%80%BC%22%5D%0A%20%20F3%5B%22%E6%8A%95%E5%BD%B1%20F%203M%22%5D%20--%3E%20PV%0A%20%20F6%5B%22%E6%8A%95%E5%BD%B1%20F%206M%22%5D%20--%3E%20PV%0A%20%20BS%5B%223s6s%20%2F%20%E6%8C%87%E6%95%B0%E5%9F%BA%E5%B7%AE%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20F6%0A%20%20IRS%5B%22%E5%9B%BA%E5%AE%9A%E5%AF%B9%E6%B5%AE%E5%8A%A8%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20F3%0A%20%20PV%20--%3E%20R1%5B%22%E6%8A%98%E7%8E%B0%E5%85%B3%E9%94%AE%2001%22%5D%0A%20%20PV%20--%3E%20R2%5B%223M%20%E6%8A%95%E5%BD%B1%2001%22%5D%0A%20%20PV%20--%3E%20R3%5B%226M%20%E6%8A%95%E5%BD%B1%2001%22%5D%0A%20%20R2%20--%3E%20H%5B%22%E7%94%A8%E4%B8%A4%20tenor%20%E4%BA%92%E6%8D%A2%E7%AF%AE%E5%AD%90%E5%AF%B9%E5%86%B2%22%5D%0A%20%20R3%20--%3E%20H%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单币种基差互换交换两个浮动指数，把期限或指数价差变成可交易曲线，而不是单曲线恒等式的残差。</li><li>Mercurio（2009）、Bianchetti（2010）、Fujii–Shimada–Takahashi（2010）给出危机后多曲线公式与有抵押自助。</li><li>风险是折现 01 加两列投影关键 01；一因子短端模型无法内生期限基差。</li><li>与互换价差、交叉货币基差科目分离；LIBOR 时代的 3s6s 故事不能原样贴到 SOFR。</li><li>LMM/HJM 可以耦合多条 tenor，但流动性通常只支撑把基差当慢因子或冻结。</li><li>出处：Mercurio, 2009；Bianchetti, <em>Risk</em>, 2010；Fujii, Shimada &amp; Takahashi, 2010；Johannes &amp; Sundaresan, <em>Journal of Finance</em>, 2007。</li></ul>',2))])}const F=i(E,[["render",d]]);export{m as __pageData,F as default};
